import Foundation
import XCTest
@testable import MacScope

/// Item 1251 (SW5): controls for the declarations-v1 type-atlas text format.
/// Selector, grammar, limit and refusal expectations are proposals frozen by this file.
/// Legacy JSON literals are transcribed from the sealed projection and sorted-key serializer,
/// not generated by the renderer.
@MainActor
final class TypeAtlasDeclarationProposalTests: XCTestCase {
    private let command = "list-image-types"
    private let owner = UUID(uuidString: "00000000-0000-0000-0000-000000000001")!
    private let otherOwner = UUID(uuidString: "00000000-0000-0000-0000-000000000002")!
    private let format = "declarations-v1"
    private let header = "// declarations-v1; retained facts only; source completeness unknown.\n"
    private let stale = "staleCursor: the list changed or the cursor belongs to another list; restart without a cursor"
    private enum Route: CaseIterable { case inline, asynchronous, attached, mcpSync, mcpAsync }

    // Source oracle: TypeAtlas.swift:9-57; TypeAtlasPages.swift:177-189,260-307;
    // ImageSelector.swift:124-132; ScriptValue.swift:72-78. UUID is a fixed fixture.
    private let fullRow = #"{"conformances":[],"evidence":"descriptor","id":{"address":"0x1000","kind":"objcClass","slot":0},"imageSlot":0,"kind":"objcClass","members":[],"methods":[],"name":"A","superclass":null,"users":[]}"#
    private let namesRow = #"{"id":{"address":"0x1000","kind":"objcClass","slot":0},"imageSlot":0,"kind":"objcClass","name":"A"}"#
    private let emptyUnpaged = #"{"imageOwner":"00000000-0000-0000-0000-000000000001","imageSlot":0,"total":0,"types":[]}"#
    private let emptyPage = #"{"imageOwner":"00000000-0000-0000-0000-000000000001","imageSlot":0,"isTruncated":false,"nextCursor":null,"rows":[],"sourceComplete":null,"total":0}"#

    private func unpagedOracle(_ row: String) -> String {
        #"{"imageOwner":"00000000-0000-0000-0000-000000000001","imageSlot":0,"total":1,"types":["# + row + "]}"
    }
    private func pageOracle(_ row: String) -> String {
        #"{"imageOwner":"00000000-0000-0000-0000-000000000001","imageSlot":0,"isTruncated":false,"nextCursor":null,"rows":["# + row + #"],"sourceComplete":null,"total":1}"#
    }
    private func entry(_ name: String = "A", kind: TypeAtlasKind = .objcClass,
                       address: UInt64 = 0x1000, slot: ImageSlot = .primary) -> TypeAtlasEntry {
        .init(id: .init(slot: slot, kind: kind, key: .address(address)), kind: kind,
              name: name, superclass: nil, members: [], conformances: [], methods: [],
              users: [], evidence: .descriptor)
    }
    private func snapshot(_ entries: [TypeAtlasEntry], definitions: [TypeDefinition] = []) -> WorkspaceSnapshot {
        var analysis = ImageAnalysis()
        analysis.typeCatalog = .init(slot: .primary, entries: entries)
        return WorkspaceSnapshot(binaries: [BinaryImage(id: owner, name: "1251", path: "/ignored/1251",
            kind: "Mach-O", architecture: "arm64")], analysisBySlot: [.primary: analysis],
            typeDefinitions: definitions)
    }
    private func store(_ snapshot: WorkspaceSnapshot) -> WorkspaceStore {
        WorkspaceStore(workspaceName: "1251 declarations proposal", snapshot: snapshot,
                       engine: AnalysisEngine(), autosaveScheduler: nil)
    }
    private func executor(_ store: WorkspaceStore) -> MCPAttachExecutor {
        var clock: UInt64 = 0
        let result = MCPAttachExecutor(store: store, api: { WorkspaceScriptingAPI(store: $0) }, now: {
            clock += 1_000_000_000
            return clock
        })
        result.setConsent(.allowed)
        return result
    }
    private func request(_ arguments: ScriptValue) throws -> Data {
        try ScriptValue.object(["jsonrpc": .string("2.0"), "id": .int(1), "method": .string("tools/call"),
            "params": .object(["name": .string(command), "arguments": arguments])]).jsonData()
    }
    private func mcpWire(_ server: MCPServer, _ args: ScriptValue, asynchronous: Bool) async throws -> Data {
        let input = try request(args)
        let data: Data?
        if asynchronous { data = await server.handleMessageAsync(input) }
        else { data = server.handleMessage(input) }
        return try XCTUnwrap(data)
    }
    private func mcpResponse(_ server: MCPServer, _ args: ScriptValue, asynchronous: Bool) async throws -> ScriptValue {
        try ScriptValue.decode(await mcpWire(server, args, asynchronous: asynchronous))
    }
    private func payloadBytes(_ response: ScriptValue) throws -> Data {
        Data(try XCTUnwrap(response["result"]?["content"]?.arrayValue?.first?["text"]?.stringValue).utf8)
    }
    private func readBytes(_ route: Route, _ args: ScriptValue, _ store: WorkspaceStore) async throws -> Data {
        let api = WorkspaceScriptingAPI(store: store)
        switch route {
        case .inline: return try api.execute(command, arguments: args).jsonData()
        case .asynchronous: return try await api.executeAsync(command, arguments: args).jsonData()
        case .attached: return try await executor(store).execute(command, args).jsonData()
        case .mcpSync, .mcpAsync:
            let response = try await mcpResponse(MCPServer(api: api), args, asynchronous: route == .mcpAsync)
            XCTAssertEqual(response["result"]?["isError"], .bool(false))
            return try payloadBytes(response)
        }
    }
    private func read(_ route: Route, _ args: [String: ScriptValue], _ store: WorkspaceStore) async throws -> ScriptValue {
        try ScriptValue.decode(await readBytes(route, .object(args), store))
    }
    private func direct(_ snapshot: WorkspaceSnapshot, _ args: [String: ScriptValue] = [:]) throws -> ScriptValue {
        try WorkspaceScriptingAPI.snapshotTypeListRead(command, arguments: .object(args), snapshot: snapshot)
    }
    private func declarations(_ snapshot: WorkspaceSnapshot, _ extra: [String: ScriptValue] = [:]) throws -> ScriptValue {
        var args = extra
        args["format"] = .string(format)
        return try direct(snapshot, args)
    }
    private func text(_ value: ScriptValue) throws -> String { try XCTUnwrap(value["text"]?.stringValue) }
    private func fields(_ value: ScriptValue) throws -> [String: ScriptValue] {
        guard case .object(let result) = value else { throw ScriptingError.invalidArgument("test expected object") }
        return result
    }
    private func assertBudget(_ body: () throws -> Void, unit: MCPRefusalBudget.Unit? = nil,
                              limit: Int64? = nil, file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertThrowsError(try body(), file: file, line: line) { error in
            guard case ScriptingError.structuredRefusal(let refusal) = error else {
                return XCTFail("expected atomic structured budget refusal, got \(error)", file: file, line: line)
            }
            XCTAssertEqual(refusal.code, .budgetExceeded, file: file, line: line)
            XCTAssertFalse(refusal.retryable, file: file, line: line)
            if let unit { XCTAssertEqual(refusal.budget?.unit, unit, file: file, line: line) }
            if let limit { XCTAssertEqual(refusal.budget?.limit, limit, file: file, line: line) }
        }
    }

    /// SPEC 9(a,n), 4,14. Absent/null format must preserve each old route's exact bytes.
    func testProposalDefaultRouteByArgumentMatrixHasFrozenNonemptyAndEmptyBytes() async throws {
        let cases: [([String: ScriptValue], Bool, Bool, Bool)] = [
            ([:], false, false, false), (["page": .bool(false)], false, false, false),
            (["limit": .int(1)], false, false, false), (["kind": .string("objcClass")], false, false, false),
            (["page": .bool(true)], true, false, false),
            (["page": .bool(true), "fields": .string("full")], true, false, false),
            (["fields": .string("full")], true, false, false),
            (["fields": .string("names")], true, true, false),
            (["page": .bool(true), "fields": .string("names")], true, true, false),
            (["page": .bool(true), "kind": .string("objcClass"), "name": .string("A")], true, false, false),
            (["name": .string("A")], true, false, false),
            (["nameContains": .string("a")], true, false, false),
            (["page": .bool(true), "name": .string("missing")], true, false, true),
            (["kind": .string("swiftStruct")], false, false, true),
        ]
        for empty in [false, true] {
            let target = store(snapshot(empty ? [] : [entry()]))
            for route in Route.allCases {
                for (arguments, paged, names, noMatch) in cases {
                    let expected = empty || noMatch ? (paged ? emptyPage : emptyUnpaged)
                        : (paged ? pageOracle(names ? namesRow : fullRow) : unpagedOracle(fullRow))
                    let absent = try await readBytes(route, .object(arguments), target)
                    var withNull = arguments
                    withNull["format"] = .null
                    let null = try await readBytes(route, .object(withNull), target)
                    XCTAssertEqual(absent, Data(expected.utf8), "\(route), \(arguments)")
                    XCTAssertEqual(null, Data(expected.utf8), "\(route), null selector, \(arguments)")
                    XCTAssertEqual(absent, null)
                }
            }
        }
    }

    /// SPEC 9(a,i,n), 4,14. Positive legacy continuation has independently frozen bytes.
    func testProposalDefaultCursorSuccessorHasFrozenBytesOnEveryRoute() async throws {
        let full = #"{"imageOwner":"00000000-0000-0000-0000-000000000001","imageSlot":0,"isTruncated":false,"nextCursor":null,"rows":[{"conformances":[],"evidence":"descriptor","id":{"address":"0x2000","kind":"objcClass","slot":0},"imageSlot":0,"kind":"objcClass","members":[],"methods":[],"name":"B","superclass":null,"users":[]}],"sourceComplete":null,"total":2}"#
        let names = #"{"imageOwner":"00000000-0000-0000-0000-000000000001","imageSlot":0,"isTruncated":false,"nextCursor":null,"rows":[{"id":{"address":"0x2000","kind":"objcClass","slot":0},"imageSlot":0,"kind":"objcClass","name":"B"}],"sourceComplete":null,"total":2}"#
        let target = store(snapshot([entry("A", address: 0x1000), entry("B", address: 0x2000)]))
        for route in Route.allCases {
            for mode in ["full", "names"] {
                let first = try await read(route, ["page": .bool(true), "limit": .int(1), "fields": .string(mode)], target)
                let cursor = try XCTUnwrap(first["nextCursor"]?.stringValue)
                XCTAssertEqual(try cursorParts(cursor)[3], "1")
                let expected = Data((mode == "full" ? full : names).utf8)
                let input: [String: ScriptValue] = ["page": .bool(true), "limit": .int(1),
                    "fields": .string(mode), "cursor": .string(cursor)]
                let absent = try await readBytes(route, .object(input), target)
                var withNull = input; withNull["format"] = .null
                let null = try await readBytes(route, .object(withNull), target)
                XCTAssertEqual(absent, expected, "\(route), \(mode), legacy cursor")
                XCTAssertEqual(null, expected, "\(route), \(mode), legacy cursor, null selector")
                XCTAssertEqual(absent, null)
            }
        }
    }

    /// SPEC 4,14 wire boundary. Include the fixed envelope and the fixture's generation.
    func testProposalDefaultCompleteMCPFramesMatchSourceDerivedEnvelopeBytes() async throws {
        // Only the generation UUID is runtime fixture state. All payload/outer syntax is frozen
        // from ScriptingGenerationCapture:205-223 and MCPStructuredResult:31-49, not the patch.
        let cases: [([String: ScriptValue], String)] = [
            ([:], unpagedOracle(fullRow)), (["page": .bool(true)], pageOracle(fullRow)),
            (["fields": .string("names")], pageOracle(namesRow)),
            (["name": .string("absent")], emptyPage),
        ]
        for empty in [false, true] {
            let target = store(snapshot(empty ? [] : [entry()]))
            let generation = target.snapshot.analysisGenerationID.uuidString
            for asynchronous in [false, true] {
                for (args, nonempty) in cases {
                    let payload = empty ? (args.isEmpty ? emptyUnpaged : emptyPage) : nonempty
                    let quotedPayload = payload.replacingOccurrences(of: "\\", with: "\\\\")
                        .replacingOccurrences(of: "\"", with: "\\\"")
                    let expected = "{\"id\":1,\"jsonrpc\":\"2.0\",\"result\":{\"_meta\":{\"generation\":\"" + generation
                        + "\"},\"content\":[{\"text\":\"" + quotedPayload
                        + "\",\"type\":\"text\"},{\"text\":\"{\\\"generation\\\":\\\"" + generation
                        + "\\\"}\",\"type\":\"text\"}],\"isError\":false}}"
                    for selector in [Optional<ScriptValue>.none, .some(.null)] {
                        var input = args; if let selector { input["format"] = selector }
                        let wire = try await mcpWire(MCPServer(api: WorkspaceScriptingAPI(store: target)),
                            .object(input), asynchronous: asynchronous)
                        XCTAssertEqual(wire, Data(expected.utf8))
                    }
                }
            }
        }
    }

    /// SPEC 9(a,n). Old failure details are source literals, not a second-path oracle.
    func testProposalAbsentAndNullSelectorPreserveDefaultRefusals() async throws {
        let cases: [([String: ScriptValue], String)] = [
            (["page": .bool(false), "fields": .string("names")], "name, nameContains and fields require page:true"),
            (["cursor": .string("x")], "cursor requires page:true"),
            (["fields": .string("x")], "fields must be full or names"),
        ]
        for (args, detail) in cases {
            for selector in [Optional<ScriptValue>.none, .some(.null)] {
                var input = args
                if let selector { input["format"] = selector }
                let target = store(snapshot([entry()]))
                for route in [Route.inline, .asynchronous, .attached] {
                    do { _ = try await read(route, input, target); XCTFail("default refusal disappeared") }
                    catch { XCTAssertEqual(error as? ScriptingError, .invalidArgument(detail)) }
                }
            }
        }
    }

    /// SPEC 9(n),14. MCPServer:1244-1247 + MCPToolArgumentError:44-79.
    func testProposalFrozenUnknownArgumentRefusalBytesOnBothTransports() async throws {
        let legacy = #"{"error":"refused","refusal":{"allowed":["cursor","fields","image","kind","limit","name","nameContains","page"],"code":"malformedInput","detail":"Field 'zzz' is not an allowed argument.","field":"zzz","retryable":false}}"#
        let selected = #"{"error":"refused","refusal":{"allowed":["cursor","fields","format","image","kind","limit","name","nameContains","page"],"code":"malformedInput","detail":"Field 'zzz' is not an allowed argument.","field":"zzz","retryable":false}}"#
        for selector in [Optional<ScriptValue>.none, .some(.null), .some(.string(format))] {
            let expected = selector == .some(.string(format)) ? selected : legacy
            var input: [String: ScriptValue] = ["zzz": .bool(true)]
            if let selector { input["format"] = selector }
            XCTAssertThrowsError(try HeadlessAutomationAuthority.validateDiagnosed(command: command, arguments: .object(input))) {
                guard let error = $0 as? ToolArgumentError else { return XCTFail("wrong argument error: \($0)") }
                XCTAssertEqual(try? error.refusal.value.jsonData(), Data(expected.utf8))
            }
            for asynchronous in [false, true] {
                let response = try await mcpResponse(MCPServer(api: WorkspaceScriptingAPI(store: store(snapshot([])))),
                    .object(input), asynchronous: asynchronous)
                XCTAssertEqual(response["result"]?["isError"], .bool(true))
                XCTAssertEqual(try payloadBytes(response), Data(expected.utf8))
            }
        }
    }

    /// SPEC 14 discovery exception. Owner authorized this one addition, not a description rewrite.
    func testProposalDiscoveryGoldensAddOnlyFormatAndKeepSummaryAndInstructions() async throws {
        let arguments = #"["image","kind","limit","page","cursor","name","nameContains","fields","format"]"#
        let summary = #"RX-02a Type Atlas (read-only): the types of one image — Objective-C classes, categories and protocols (name only), Swift classes/structs/enums, and the workspace user types — with members (offset + evidence: descriptor|staticEvaluation|authored|unknown; an unknown layout has a null offset), conformances, methods (selector, IMP, selref users) and users (classref xref sources, or addresses a user type is applied to). Reads the primary image by default; `image` (a slot index or an image-owner ID) selects another loaded image. Optional `kind` filters (swiftClass|swiftStruct|swiftEnum|objcClass|objcCategory|objcProtocol|userType); optional `limit` caps the rows. The default reply (including an explicit `limit` and `page: false`) is a bounded prefix of full rows with a byte allowance C = 166,000: `total` is the whole-filter total and `types.count` the admitted prefix; unnamed positional Swift vtable slots may be replaced by `unnamedVtableSlots` {count, first, last} with `vtableSummaryVersion: 1`; when rows are omitted the reply carries `isTruncated: true` and `nextCursor`, which is continued as `cursor` with `page: true`, `fields: "full"`, `limit: 1` and the original image/kind. The complete frame is guaranteed within 180,000 bytes only for an encoded JSON request-id length I <= 13,000, since C + I + 1,000 <= 180,000; larger IDs are not clipped and have no such guarantee. Small replies keep their original shape. For Swift rows, `hasUnassignedSwiftConformanceRecords` reports whether recovered records in the image lack a unique local owner; false does not certify extraction completeness. The result carries `imageSlot`, `imageOwner`, `total` and `types`. `page: true` returns {rows, total, isTruncated, nextCursor, sourceComplete, imageSlot, imageOwner}; `cursor` continues from `nextCursor`, `name` / `nameContains` filter by name, and `fields: "names"` returns names-only rows. A non-null `name`, `nameContains` or `fields` without `page` also returns a page."#
        let schema = #"{"additionalProperties":false,"properties":{"cursor":{"description":"Continue from nextCursor; restart if stale. A nextCursor from a default reply needs page:true, fields:\"full\", limit:1 and the original image\/kind; page cursors keep their own filters and fields.","maxLength":1024,"type":"string"},"fields":{"enum":["full","names"],"type":"string"},"format":{"enum":["declarations-v1",null],"type":["string","null"]},"image":{"anyOf":[{"maximum":2147483647,"minimum":0,"type":"integer"},{"type":"string"}],"description":"Image to read: a slot index (0 is the primary image) or an image-owner ID (UUID). Omit for the primary image."},"kind":{"enum":["swiftClass","swiftStruct","swiftEnum","objcClass","objcCategory","objcProtocol","userType","importedType"],"type":"string"},"limit":{"maximum":10000,"minimum":0,"type":"integer"},"name":{"maxLength":1024,"minLength":1,"type":"string"},"nameContains":{"maxLength":1024,"minLength":1,"type":"string"},"page":{"description":"Opt in to a bounded Type Atlas page with filters and continuation; name, nameContains or fields without page also page.","type":"boolean"}},"type":"object"}"#
        let info = try XCTUnwrap(HeadlessAutomationAuthority.availableCommands.first { $0.name == command })
        XCTAssertEqual(try ScriptValue.array(info.arguments.map(ScriptValue.string)).jsonData(), Data(arguments.utf8))
        XCTAssertEqual(info.summary, summary); XCTAssertFalse(info.mutates)
        XCTAssertEqual(try HeadlessAutomationAuthority.inputSchema(for: info).jsonData(), Data(schema.utf8))
        let target = store(snapshot([entry()])), api = WorkspaceScriptingAPI(store: target)
        let inline = try api.execute("commands")
        let asynchronous = try await api.executeAsync("commands", arguments: .object([:]))
        let attached = try await executor(target).execute("commands", .object([:]))
        for catalog in [inline, asynchronous, attached] {
            let row = try XCTUnwrap(catalog.arrayValue?.first { $0["name"] == .string(command) })
            XCTAssertEqual(try XCTUnwrap(row["arguments"]).jsonData(), Data(arguments.utf8))
            XCTAssertEqual(row["summary"], .string(summary)); XCTAssertEqual(row["mutates"], .bool(false))
        }
        let toolsRequest = try ScriptValue.object(["jsonrpc": .string("2.0"), "id": .int(2),
            "method": .string("tools/list")]).jsonData()
        let server = MCPServer(api: api)
        let tools = try ScriptValue.decode(XCTUnwrap(server.handleMessage(toolsRequest)))
        let tool = try XCTUnwrap(tools["result"]?["tools"]?.arrayValue?.first { $0["name"] == .string(command) })
        XCTAssertEqual(tool["description"], .string(summary))
        XCTAssertEqual(try XCTUnwrap(tool["inputSchema"]).jsonData(), Data(schema.utf8))
        let instructions = """
        MacScope MCP server for one Mach-O binary that is already open; there is no open-file step.
        While analysis runs, tools reply notReady; call info (waitForReadyMs from 0 to 25000 waits) until it reports ready.
        Addresses are hex strings such as "0x100003f20", in arguments and in replies.
        Evidence: each completed workspace read appends a text block {generation: UUID} and returns _meta.generation. The first content block keeps its legacy shape. Pass that UUID as optional basedOnGeneration on a write; staleEvidence names basedOnGeneration and currentGeneration without applying the write. Successful writes return the resulting generation; changed annotations can advance it even without reanalysis, so chain the new reply generation or read again. Navigator staleCursor is unchanged.
        Start with info, then list-image-types (classes, categories, protocols, Swift types) or search (mode text, regex or hex), then decompile a function by name or address.
        Graph: callers, callees and xrefs; callers of an _objc_msgSend$<selector> stub lists that selector's call sites.
        Names: name-at, functions, symbols and strings; demangle renders one Swift mangled name.
        Images: search, callers, callees and xrefs rows carry imageSlot; imageSlot or image selects one loaded image; without it, search reads every loaded image and other tools read the primary image.
        Limits depend on image size: large scans and results stop at a budget and say so (a refusal or isTruncated); narrow with limit, kind, imageSlot or a search cursor and retry; a list-image-types explicit limit is still subject to its byte allowance, so continue a default nextCursor as cursor with page:true, fields:"full", limit:1 and the original image/kind.
        Type Atlas: list-image-types total is the whole-filter total and types.count is the admitted default prefix; an explicit limit is additionally byte-capped, and unnamed vtable slots may be summarized as unnamedVtableSlots with vtableSummaryVersion 1. When isTruncated, pass nextCursor as cursor with page:true, fields:"full", limit:1 and the original image/kind. For browsing use page:true, fields:"names" (kind, name or nameContains narrow it); a full-detail page does not carry the default reply's 180,000-byte bound.
        Tools whose description ends "(mutates the workspace)" change workspace state, for example names, comments, types, code/data markup, xrefs, patches, bookmarks, segments, navigation, undo or the open workspace; every other tool is read-only.
        Groups: reads (info, functions, symbols, strings, sections, search, decompile, instructions, read-bytes), graph (callers, callees, xrefs, open-claim, record-callee-outcome, claim-status), types (list-image-types, list-types), edits (the mutating tools), navigator-* (evidence navigator); commands lists the scripting commands.
        """
        XCTAssertEqual(Data(MCPServer.sessionInstructions.utf8), Data(instructions.utf8))
    }

    /// SPEC 9(a), selectors/routing. The opt-in does not inherit attached unpaged clamping.
    func testProposalSelectorValidationAndImpliedAttachedPageLimit() async throws {
        let target = store(snapshot((0..<101).map { entry("C\($0)", address: UInt64(0x1000 + $0 * 16)) }))
        let implied: [[String: ScriptValue]] = [
            ["format": .string(format)], ["format": .string(format), "page": .null],
        ]
        for route in Route.allCases {
            for args in implied {
                let first = try await read(route, args, target)
                XCTAssertEqual(first["total"], .int(101)); XCTAssertEqual(first["isTruncated"], .bool(true))
                XCTAssertEqual(try text(first).components(separatedBy: "objc-class ").count - 1, 100)
                XCTAssertEqual(try cursorParts(XCTUnwrap(first["nextCursor"]?.stringValue))[3], "100")
            }
        }
        for route in [Route.inline, .asynchronous, .attached] {
            do {
                _ = try await read(route, ["format": .string(format), "page": .bool(false)], target)
                XCTFail("explicit unpaged declarations should refuse")
            } catch {
                XCTAssertEqual(error as? ScriptingError, .invalidArgument("declarations-v1 requires page:true or an omitted page"))
            }
        }
        for bad in [ScriptValue.string("other"), .int(1), .bool(true), .array([])] {
            XCTAssertThrowsError(try direct(target.snapshot, ["format": bad])) {
                XCTAssertEqual($0 as? ScriptingError, .invalidArgument("format must be declarations-v1 or null"))
            }
            XCTAssertThrowsError(try HeadlessAutomationAuthority.validateDiagnosed(command: command,
                arguments: .object(["format": bad]))) {
                guard let refusal = ($0 as? ToolArgumentError)?.refusal else { return XCTFail("wrong selector refusal") }
                XCTAssertEqual(refusal.field, "format"); XCTAssertEqual(refusal.expected, "string or null")
                XCTAssertEqual(refusal.allowed, ["declarations-v1"])
            }
        }
    }

    /// SPEC 9(b,c). Equal names are not identities; cached catalog order is authoritative.
    func testProposalTwoOwnersAndDuplicateNamesKeepSlotIdentityAndOrder() async throws {
        let slot = ImageSlot(rawValue: 1)
        var primary = ImageAnalysis(), secondary = ImageAnalysis()
        primary.typeCatalog = .init(slot: .primary, entries: [entry("Same", address: 0x2000), entry("Same", address: 0x1000)])
        secondary.typeCatalog = .init(slot: slot, entries: [entry("Same", address: 0x3000, slot: slot)])
        let snap = WorkspaceSnapshot(binaries: [
            BinaryImage(id: owner, name: "one", path: "/one", kind: "Mach-O", architecture: "arm64"),
            BinaryImage(id: otherOwner, name: "two", path: "/two", kind: "Mach-O", architecture: "arm64", slot: slot),
        ], analysisBySlot: [.primary: primary, slot: secondary])
        for route in Route.allCases {
            let target = store(snap)
            let a = try await read(route, ["format": .string(format), "image": .int(0)], target)
            let b = try await read(route, ["format": .string(format), "image": .string(otherOwner.uuidString)], target)
            XCTAssertEqual(a["imageOwner"], .string(owner.uuidString)); XCTAssertEqual(a["imageSlot"], .int(0))
            XCTAssertEqual(b["imageOwner"], .string(otherOwner.uuidString)); XCTAssertEqual(b["imageSlot"], .int(1))
            XCTAssertEqual(a["total"], .int(2)); XCTAssertEqual(b["total"], .int(1))
            let at = try text(a), bt = try text(b)
            XCTAssertEqual(at.components(separatedBy: "objc-class \"Same\" {").count - 1, 2)
            let first = try XCTUnwrap(at.range(of: "\"address\" = \"0x2000\""))
            let second = try XCTUnwrap(at.range(of: "\"address\" = \"0x1000\""))
            XCTAssertLessThan(first.lowerBound, second.lowerBound)
            XCTAssertFalse(at.contains("0x3000")); XCTAssertFalse(bt.contains("0x1000"))
            XCTAssertTrue(bt.contains("\"slot\" = 1"))
        }
    }

    /// SPEC 9(d). PROPOSAL grammar; retained nil values never become a type or zero.
    func testProposalUnknownMemberAndCompleteSmallDeclarationHaveExactText() throws {
        var unknown = entry()
        unknown.members = [.init(name: "m", type: nil, offset: nil, evidence: .unknown)]
        let expected = header + """
        objc-class "A" {
          "conformances" = [];
          "evidence" = "descriptor";
          "id" = {"address" = "0x1000"; "kind" = "objcClass"; "slot" = 0};
          "imageSlot" = 0;
          member {"evidence" = "unknown"; "name" = "m"; "offset" = unknown; "type" = unknown};
          methods = [];
          "superclass" = unknown;
          "users" = [];
        }
        """ + "\n"
        let value = try declarations(snapshot([unknown]))
        XCTAssertEqual(try text(value), expected)
        XCTAssertEqual(value["format"], .string(format)); XCTAssertNil(value["rows"]); XCTAssertNil(value["types"])
        XCTAssertEqual(value["sourceComplete"], .null)
        XCTAssertEqual(try text(declarations(snapshot([]))), header)
    }

    /// SPEC 9(e). ImageTypeCatalog:333-375 distinguishes nil, empty and resolved tables.
    func testProposalSwiftTableStatesAndPositionalLabelsRemainFacts() throws {
        let metadata = SwiftMetadataMethod(source: .vtable, index: 0, descriptorAddress: 0x5000,
            implementation: 0x6000, flags: 0x10)
        var analysis = ImageAnalysis()
        analysis.swiftTypes = [
            SwiftTypeDescriptor(kind: .class, name: "Nil", descriptorAddress: 0x1000, methods: nil),
            SwiftTypeDescriptor(kind: .class, name: "Empty", descriptorAddress: 0x2000, methods: []),
            SwiftTypeDescriptor(kind: .class, name: "Resolved", descriptorAddress: 0x3000, methods: [metadata]),
        ]
        let snap = WorkspaceSnapshot(binaries: [BinaryImage(id: owner, name: "swift", path: "/swift",
            kind: "Mach-O", architecture: "arm64")], analysisBySlot: [.primary: analysis])
        let rows = try XCTUnwrap(direct(snap, ["page": .bool(true)])["rows"]?.arrayValue)
        XCTAssertEqual(rows.map { $0["swiftMethodTableResolved"] }, [.bool(false), .bool(true), .bool(true)])
        XCTAssertEqual(rows[0]["methods"], .array([])); XCTAssertEqual(rows[1]["methods"], .array([]))
        let rendered = try text(declarations(snap))
        XCTAssertTrue(rendered.contains("\"swiftMethodTableResolved\" = false;"))
        XCTAssertTrue(rendered.contains("  method-table = unresolved;\n"))
        XCTAssertEqual(rendered.components(separatedBy: "  method-table = resolved;\n").count - 1, 2)
        XCTAssertEqual(rendered.components(separatedBy: "\"swiftMethodTableResolved\" = true;").count - 1, 2)
        XCTAssertTrue(rendered.contains("method-record {\"implementation\" = \"0x6000\"; \"isClassMethod\" = false; \"name\" = \"vtable #0 (name unknown)\";"))
        XCTAssertFalse(rendered.contains("func ")); XCTAssertFalse(rendered.contains("vtable #0("))
        var legacy = entry("Legacy", kind: .swiftClass)
        legacy.swiftMethodTableResolved = nil
        let legacyText = try text(declarations(snapshot([legacy])))
        XCTAssertTrue(legacyText.contains("\"swiftMethodTableResolved\" = unknown;"))
        XCTAssertTrue(legacyText.contains("  method-table = unknown;\n"))
    }

    /// SPEC 9(f), B3. All authored TypeKinds lose their kind in the existing projection.
    func testProposalEveryAuthoredTypeKindIsExplicitlyKindUnknownAndUntouched() throws {
        let definitions = [TypeKind.struct, .union, .enum, .typedef].enumerated().map { index, kind in
            TypeDefinition(kind: kind, name: "User\(index)", fields: [.init(name: "value", type: "int")])
        }
        let snap = snapshot([], definitions: definitions)
        let target = store(snap)
        let before = target.snapshot.typeDefinitions
        let value = try WorkspaceScriptingAPI(store: target).execute(command, arguments: .object(["format": .string(format)]))
        let rendered = try text(value)
