        XCTAssertEqual(rendered.components(separatedBy: "user-type(kind=unknown)").count - 1, 4)
        XCTAssertEqual(target.snapshot.typeDefinitions, before)
        XCTAssertEqual(before.map(\.kind), [.struct, .union, .enum, .typedef])
