    /// SPEC 9(g). Existing node/byte omission markers survive, rather than invented bodies.
    func testProposalNamesAndBothUnderlyingOmissionReasonsAreExplicit() throws {
        let named = try text(declarations(snapshot([entry()]), ["fields": .string("names")]))
        XCTAssertTrue(named.contains("  projection = names-only;\n"))
        XCTAssertFalse(named.contains("  members = [];"))
        let truncated = try text(declarations(snapshot([entry(String(repeating: "a", count: 20_000))]),
            ["fields": .string("names")]))
        XCTAssertTrue(truncated.contains("\"nameByteLength\" = 20000;"))
        XCTAssertTrue(truncated.contains("\"nameTruncated\" = true;"))
        XCTAssertTrue(truncated.contains("  projection = names-only;\n"))
        var nodes = entry("Nodes", address: 0x2000)
        nodes.users = Array(repeating: 0x1000, count: 65_488) // 49 + 65,488 > 65,536.
        var bytes = entry("Bytes", address: 0x3000)
        bytes.users = Array(repeating: UInt64.max, count: 10_000) // >196,608 JSON bytes, <65,536 nodes.
        let snap = snapshot([nodes, bytes, entry("Tail", address: 0x4000)])
        let old = try direct(snap, ["page": .bool(true)])
        let rows = try XCTUnwrap(old["rows"]?.arrayValue)
        XCTAssertEqual(rows[0]["fullRowReason"], .string("nodes"))
        XCTAssertEqual(rows[1]["fullRowReason"], .string("bytes"))
        let value = try declarations(snap), rendered = try text(value)
        XCTAssertEqual(rendered.components(separatedBy: "  projection = omitted;\n").count - 1, 2)
        XCTAssertTrue(rendered.contains("\"fullRowReason\" = \"nodes\";"))
        XCTAssertTrue(rendered.contains("\"fullRowReason\" = \"bytes\";"))
        XCTAssertTrue(rendered.contains("objc-class \"Tail\" {"))
        XCTAssertEqual(value["total"], .int(3)); XCTAssertEqual(value["nextCursor"], .null)
    }

    /// SPEC 9(h). PROPOSAL scalar grammar, including hostile member types and selectors.
    func testProposalHostileScalarsHaveLiteralEscapesAndSeparateWireByteAccounting() throws {
        let hostile = "A\u{1}\n\"\\{};é\u{202e}😀"
        let escaped = #""A\u{1}\u{a}\"\\{};\u{e9}\u{202e}\u{1f600}""#
        var hostileEntry = entry(hostile)
        hostileEntry.members = [.init(name: hostile, type: hostile, offset: nil, evidence: .unknown)]
        hostileEntry.methods = [.init(name: hostile, implementation: nil)]
        let value = try declarations(snapshot([hostileEntry])), rendered = try text(value)
        XCTAssertTrue(rendered.contains("objc-class " + escaped + " {\n"))
        XCTAssertTrue(rendered.contains("\"name\" = " + escaped))
        XCTAssertTrue(rendered.contains("\"type\" = " + escaped))
        XCTAssertTrue(rendered.contains("  method-record {"))
        XCTAssertFalse(rendered.contains("é")); XCTAssertFalse(rendered.contains("\u{202e}"))
        XCTAssertTrue(rendered.unicodeScalars.allSatisfy { $0.value == 10 || (32...126).contains($0.value) })
        XCTAssertEqual(hostile.utf8.count, 17) // 8 ASCII bytes, é:2, bidi:3, emoji:4.
        XCTAssertEqual(escaped.utf8.count, 43) // 2 quotes + 1+5+5+2+2+3+6+8+9.
        XCTAssertNotEqual(hostile.count, hostile.utf8.count)
        let inner = try value.jsonData()
        for protocolVersion in [MCPResultProtocol.legacy, .structured] {
            let envelope = MCPStructuredResult.successEnvelope(protocolVersion: protocolVersion,
                tool: command, output: value, legacyText: String(decoding: inner, as: UTF8.self), isError: false)
            let frame = ScriptValue.object(["jsonrpc": .string("2.0"), "id": .int(1), "result": envelope])
            let outer = try frame.jsonData()
            XCTAssertLessThanOrEqual(inner.count, 524_288)
            XCTAssertLessThanOrEqual(outer.count, 2 * inner.count + 4_096)
            XCTAssertGreaterThan(outer.count, inner.count)
            XCTAssertEqual(try ScriptValue.decode(outer), frame)
        }
        XCTAssertGreaterThan(inner.count, rendered.utf8.count)
        XCTAssertLessThanOrEqual(rendered.utf8.count, 196_608)
    }

    /// SPEC 9(h,j). PROPOSAL per-string refusal is atomic, not silent truncation.
    func testProposalStringCapBoundaryAndOverCapRefusal() throws {
        let atCap = entry(String(repeating: "x", count: 8_192))
        XCTAssertTrue(try text(declarations(snapshot([atCap]))).contains(String(repeating: "x", count: 8_192)))
        let over = entry(String(repeating: "x", count: 8_193))
        var released: ScriptValue?
        assertBudget({ released = try declarations(snapshot([entry(), over])) }, unit: .bytes, limit: 8_192)
        XCTAssertNil(released)
        // Multibyte strings are capped by UTF-8 bytes, not Swift Character count.
        let multibyte = entry(String(repeating: "é", count: 4_097))
        assertBudget({ _ = try declarations(snapshot([multibyte])) }, unit: .bytes, limit: 8_192)
    }

    /// SPEC 9(i). PROPOSAL cursor is l1 with a representation/order-version fingerprint.
    func testProposalTwoPagesAndBidirectionalForeignCursorRefusalMatrix() throws {
        let snap = snapshot([entry("A"), entry("B", address: 0x2000)])
        let first = try declarations(snap, ["limit": .int(1)])
        let cursor = try XCTUnwrap(first["nextCursor"]?.stringValue)
        let legacyFirst = try direct(snap, ["page": .bool(true), "limit": .int(1)])
        let legacy = try XCTUnwrap(legacyFirst["nextCursor"]?.stringValue)
        XCTAssertEqual(first["isTruncated"], .bool(true))
        XCTAssertTrue(try text(first).contains("objc-class \"A\" {"))
        XCTAssertFalse(try text(first).contains("objc-class \"B\" {"))
        let next = try declarations(snap, ["limit": .int(1), "cursor": .string(cursor)])
        XCTAssertTrue(try text(next).contains("objc-class \"B\" {"))
        XCTAssertEqual(next["nextCursor"], .null); XCTAssertEqual(next["isTruncated"], .bool(false))
        let parts = try cursorParts(cursor), oldParts = try cursorParts(legacy)
        XCTAssertEqual(Array(parts.prefix(5)), Array(oldParts.prefix(5)))
        XCTAssertEqual(parts[0], "l1"); XCTAssertEqual(parts[3], "1")
        XCTAssertEqual(try XCTUnwrap(UInt64(parts[5], radix: 16)) ^ XCTUnwrap(UInt64(oldParts[5], radix: 16)), 0x5357350001000001)
        for (input, isText) in [(legacy, true), (cursor, false)] {
            XCTAssertThrowsError(try direct(snap, isText
                ? ["format": .string(format), "cursor": .string(input)]
                : ["page": .bool(true), "cursor": .string(input)])) {
                XCTAssertEqual($0 as? ScriptingError, .invalidArgument(stale))
            }
        }
        for extra in [["name": ScriptValue.string("A")], ["fields": .string("names")],
                      ["kind": .string("objcClass")], ["nameContains": .string("a")]] {
            var args = extra; args["cursor"] = .string(cursor)
            XCTAssertThrowsError(try declarations(snap, args)) { XCTAssertEqual($0 as? ScriptingError, .invalidArgument(stale)) }
        }
        let fresh = snapshot([entry("A"), entry("B", address: 0x2000)])
        XCTAssertThrowsError(try declarations(fresh, ["cursor": .string(cursor)])) {
            XCTAssertEqual($0 as? ScriptingError, .invalidArgument(stale))
        }
        var foreign = parts; foreign[2] = "1"
        XCTAssertThrowsError(try declarations(snap, ["cursor": .string(Data(foreign.joined(separator: "|").utf8).base64EncodedString())])) {
            XCTAssertEqual($0 as? ScriptingError, .invalidArgument(stale))
        }
        XCTAssertEqual(try WorkspaceScriptingAPI.typeAtlasDeclarationCursor(.string(legacy)), .string(cursor))
        XCTAssertEqual(try WorkspaceScriptingAPI.typeAtlasDeclarationCursor(.string(cursor)), .string(legacy))
    }
    private func cursorParts(_ cursor: String) throws -> [String] {
        let data = try XCTUnwrap(Data(base64Encoded: cursor))
        return try XCTUnwrap(String(data: data, encoding: .utf8)).components(separatedBy: "|")
    }

    /// SPEC 9(j), B10. Existing capped first names row fits; no zero/nonadvancing cursor.
    func testProposalWorstEscapedNamesRowMakesLegacyProgressAndTextRefusesAtomically() throws {
        // 1294 contrast, kept. With 4,450 U+0001 chars in each of name, qualifiedName and id.name:
        // legacy names charge = 3 * 7 * 4,450 = 93,450 (+ under 400 key bytes) < 94,999, so the row fits;
        // declarations-v1 text renders each as \u{1} (5 bytes): 3 * 5 * 4,450 = 66,750 (+ keys)
        // > 65,536 (maximumTypeAtlasDeclarationBytes), so the text path refuses. (20,000 chars charged
        // 172,383 and is now refused on the legacy path too.)
        let hostile = String(repeating: "\u{1}", count: 4_450)
        var huge = entry(hostile, kind: .swiftStruct)
        huge.id.key = .name(hostile); huge.qualifiedName = hostile
        let snap = snapshot([huge, entry("Tail", address: 0x2000)])
        let page = try direct(snap, ["page": .bool(true), "fields": .string("names"), "limit": .int(1)])
        let rows = try XCTUnwrap(page["rows"]?.arrayValue)
        XCTAssertEqual(rows.count, 1)
        XCTAssertEqual(rows[0]["name"]?.stringValue?.utf8.count, 4_450)
        XCTAssertNil(rows[0]["nameByteLength"])
        XCTAssertLessThan(3 * 7 * 4_450 + 400, 94_999)
        XCTAssertGreaterThan(3 * 5 * 4_450, 65_536)
        XCTAssertLessThan(try rows[0].jsonData().count + 1, 196_608)
        let cursor = try XCTUnwrap(page["nextCursor"]?.stringValue)
        XCTAssertEqual(try cursorParts(cursor)[3], "1")
        let tail = try direct(snap, ["page": .bool(true), "fields": .string("names"), "cursor": .string(cursor)])
        XCTAssertEqual(tail["rows"]?.arrayValue?.first?["name"], .string("Tail"))
        assertBudget({ _ = try declarations(snap, ["fields": .string("names"), "limit": .int(1)]) }, unit: .bytes, limit: 65_536)
        // Opt-in-only defensive seam: impossible under the sealed row bounds, but never emit it.
        let impossible: ScriptValue = .object(["rows": .array([]), "total": .int(1),
            "isTruncated": .bool(true), "nextCursor": .string("nonadvancing"), "sourceComplete": .null,
            "imageSlot": .int(0), "imageOwner": .string(owner.uuidString)])
        assertBudget({ _ = try WorkspaceScriptingAPI.typeAtlasDeclarationResult(impossible, checkpoint: {}) }, unit: .rows, limit: 1)
    }

    /// SPEC 9(j), 5-6. Per-declaration and whole-page budgets cannot return a prefix.
    func testProposalOversizedDeclarationPageNodesAndDepthRefuseWithoutPartialText() throws {
        var oversized = entry("Oversized")
        oversized.members = Array(repeating: .init(name: String(repeating: "m", count: 80),
            type: "T", offset: nil, evidence: .unknown), count: 600)
        let snap = snapshot([entry("First"), oversized])
        let legacy = try direct(snap, ["page": .bool(true)])
        XCTAssertEqual(legacy["rows"]?.arrayValue?.count, 2)
        XCTAssertNil(legacy["rows"]?.arrayValue?[1]["fullRowOmitted"])
        var published: ScriptValue?
        assertBudget({ published = try declarations(snap) }, unit: .bytes, limit: 65_536)
        XCTAssertNil(published)
        let medium: ScriptValue = .object(["kind": .string("objcClass"), "name": .string("Medium"),
            "members": .array([]), "fact": .array(Array(repeating: .string(String(repeating: "a", count: 8_000)), count: 4))])
        var pageText: String?
        assertBudget({ pageText = try WorkspaceScriptingAPI.typeAtlasDeclarationText(Array(repeating: medium, count: 7), checkpoint: {}) },
            unit: .bytes, limit: 196_608)
        XCTAssertNil(pageText)
        let nodes: ScriptValue = .object(["kind": .string("objcClass"), "name": .string("Nodes"),
            "members": .array([]), "fact": .array(Array(repeating: .null, count: 65_537))])
        assertBudget({ _ = try WorkspaceScriptingAPI.typeAtlasDeclarationText([nodes], checkpoint: {}) })
        var nested: ScriptValue = .null
        for _ in 0..<18 { nested = .array([nested]) }
        let deep: ScriptValue = .object(["kind": .string("objcClass"), "name": .string("Deep"), "fact": nested])
        assertBudget({ _ = try WorkspaceScriptingAPI.typeAtlasDeclarationText([deep], checkpoint: {}) }, unit: .nodes, limit: 16)
        // Defensive final serializer seam. Real provenance is a UUID/null, never this long.
        let hugeEnvelope: ScriptValue = .object(["rows": .array([]), "total": .int(0),
            "isTruncated": .bool(false), "nextCursor": .null, "sourceComplete": .null,
            "imageSlot": .int(0), "imageOwner": .string(String(repeating: "x", count: 524_289))])
        assertBudget({ _ = try WorkspaceScriptingAPI.typeAtlasDeclarationResult(hugeEnvelope, checkpoint: {}) },
            unit: .bytes, limit: 524_288)
    }

    /// SPEC 9(k). Cancellation throws through projection, never a partial/late result.
    func testProposalCancellationAtRendererCheckpointPublishesNothing() throws {
        let row: ScriptValue = .object(["kind": .string("objcClass"), "name": .string("A"), "members": .array([])])
        for stopAt in [1, 3] { // row boundary, then inside the quoted heading, respectively.
            var visits = 0
            var published: String?
            XCTAssertThrowsError(try {
                published = try WorkspaceScriptingAPI.typeAtlasDeclarationText([row], checkpoint: {
                    visits += 1
                    if visits == stopAt { throw CancellationError() }
                })
            }()) { XCTAssertTrue($0 is CancellationError) }
            XCTAssertEqual(visits, stopAt); XCTAssertNil(published)
        }
        var pagePublished: ScriptValue?
        XCTAssertThrowsError(try {
            pagePublished = try WorkspaceScriptingAPI.snapshotTypeListRead(command,
                arguments: .object(["format": .string(format)]), snapshot: snapshot([entry()]),
                checkpoint: { throw CancellationError() })
        }()) { XCTAssertTrue($0 is CancellationError) }
        XCTAssertNil(pagePublished)
    }

    /// SPEC 9(k). MCPAttachExecutor:120,123,152 makes third grant check release-only.
    func testProposalAttachedGrantRevokedBeforeReleaseDiscardsCompletedRead() async throws {
        let target = store(snapshot([entry()]))
        let attached = executor(target)
        var grants = 0
        attached.authorize = {
            grants += 1
            return grants < 3
        }
        var published: ScriptValue?
        do {
            published = try await attached.execute(command, .object(["format": .string(format)]))
            XCTFail("revoked grant released declaration text")
        } catch { XCTAssertEqual(error as? MCPAttachExecutor.Failure, .notAuthorized) }
        XCTAssertEqual(grants, 3); XCTAssertNil(published)
    }

    /// SPEC 9(l,m). Linker remains read-only; both identity rows, one stored-member list.
    func testProposalLinkedRowsMembersAndAllCountsPreserveStructuredFactsOnEveryRoute() async throws {
        var objc = entry("_TtC4Test3Foo", address: 0x7100)
        objc.instanceSize = 16
        objc.members = [.init(name: "count", type: nil, offset: 8, evidence: .descriptor, size: 8)]
        var swift = entry("Foo", kind: .swiftClass, address: 0x8000)
        swift.qualifiedName = "Test.Foo"; swift.isGeneric = false; swift.isPrivateOrLocal = false
        swift.members = [.init(name: "count", type: "Swift.Int", offset: 8, evidence: .descriptor)]
        let snap = snapshot([objc, swift])
        let expectedCounts: ScriptValue = .object(["linked": .int(1), "membersNotMerged": .int(0),
            "abstained": .object(["runtimeNameUndecodable": .int(0), "noSwiftRow": .int(0),
                "ambiguous": .int(0), "privateOrLocal": .int(0), "generic": .int(0)])])
        for route in Route.allCases {
            let target = store(snap)
            let legacy = try await read(route, ["page": .bool(true)], target)
            let projected = try await read(route, ["format": .string(format)], target)
            for key in ["imageSlot", "imageOwner", "total", "isTruncated", "nextCursor", "sourceComplete", "swiftObjCLinks"] {
                XCTAssertEqual(projected[key], legacy[key], key)
            }
            XCTAssertEqual(projected["swiftObjCLinks"], expectedCounts)
            let rendered = try text(projected)
            XCTAssertEqual(rendered.components(separatedBy: "  member ").count - 1, 1)
            XCTAssertEqual(rendered.components(separatedBy: "objc-class ").count - 1, 1)
            XCTAssertEqual(rendered.components(separatedBy: "swift-class ").count - 1, 1)
            XCTAssertTrue(rendered.contains("\"swiftFieldType\" = \"Swift.Int\""))
            XCTAssertTrue(rendered.contains("\"swiftId\" = {\"address\" = \"0x8000\"; \"kind\" = \"swiftClass\"; \"slot\" = 0}"))
            XCTAssertTrue(rendered.contains("\"objcId\" = {\"address\" = \"0x7100\"; \"kind\" = \"objcClass\"; \"slot\" = 0}"))
            XCTAssertTrue(rendered.contains("\"membersListedOn\" = {\"address\" = \"0x7100\"; \"kind\" = \"objcClass\"; \"slot\" = 0}"))
            let filtered = try await read(route, ["format": .string(format), "kind": .string("swiftClass")], target)
            XCTAssertEqual(filtered["swiftObjCLinks"], expectedCounts)
            XCTAssertFalse(try text(filtered).contains("  member "))
        }
    }
